SELECT (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='parametros_anuales' AND column_name IN ('anio','revision','datos','creado_por','created_at'))=5 AND (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='parametros_anuales' AND index_name='PRIMARY')=2 AND (SELECT COUNT(*) FROM information_schema.table_constraints WHERE constraint_schema=DATABASE() AND table_name='parametros_anuales' AND constraint_name IN ('parametros_anuales_json','parametros_anuales_actor'))=2;
